describe('Out-of-Stock Message on Cart Addition', () => {
  beforeEach(() => {
    cy.visit('/cart');
  });

  it('should display out-of-stock message when adding an unavailable item to cart', () => {
    // Intercept the API call to get product details
    cy.intercept('GET', '/api/products/12345').as('getProduct');
    cy.get('[data-testid="add-to-cart-button"]').click();

    // Wait for the product API call
    cy.wait('@getProduct');

    // Verify the product details are displayed
    cy.get('[data-testid="product-name"]').should('contain', 'Out of Stock Item');
    cy.get('[data-testid="product-price"]').should('contain', '$99.99');

    // Verify the out-of-stock message is visible
    cy.get('[data-testid="out-of-stock-message"]').should('be.visible');
    cy.get('[data-testid="out-of-stock-message"]').should('contain', 'This item is currently out of stock');

    // Verify the add to cart button is disabled
    cy.get('[data-testid="add-to-cart-button"]').should('be.disabled');

    // Verify the cart count does not increment
    cy.get('[data-testid="cart-count"]').should('contain', '0');
  });

  it('should handle multiple out-of-stock items gracefully', () => {
    // Intercept multiple API calls for different out-of-stock products
    cy.intercept('GET', '/api/products/12345').as('getProduct1');
    cy.intercept('GET', '/api/products/67890').as('getProduct2');

    // Add the first out-of-stock item
    cy.get('[data-testid="add-to-cart-button"]').click();
    cy.wait('@getProduct1');
    cy.get('[data-testid="out-of-stock-message"]').should('be.visible');
    cy.get('[data-testid="out-of-stock-message"]').should('contain', 'This item is currently out of stock');

    // Add the second out-of-stock item
    cy.get('[data-testid="add-to-cart-button"]').click();
    cy.wait('@getProduct2');

    // Verify both out-of-stock messages are visible
    cy.get('[data-testid="out-of-stock-message"]').should('have.length.greaterThan', 1);

    // Verify the cart count remains at 0
    cy.get('[data-testid="cart-count"]').should('contain', '0');

    // Verify the add to cart button is still disabled
    cy.get('[data-testid="add-to-cart-button"]').should('be.disabled');
  });
});
